(() => {
  const name = String($json.body.conversation.meta.sender.name || '').trim();
  const phone = String($json.body.conversation.meta.sender.phone_number || '').trim();
  if (!name) return false;

  const norm = s => s.replace(/[\s()-]/g,'');
  const looksPhone = /^[+]?[\d]{7,}$/.test(norm(name));      // puro número (con +)
  const sameAsPhone = norm(name) === norm(phone);

  return !(looksPhone || sameAsPhone);
})()
}}

