// Code node — Run Once for All Items
// Detecta automáticamente si es una lista de imágenes o texto con imagen única
// Caso 1: Texto descriptivo + link único → separa en text_clean + image_link
// Caso 2: Lista de imágenes múltiples → crea un item por cada link

const items = $input.all();
const out = [];

for (const item of items) {
  const text = item.json?.text ?? '';

  // Encontrar TODOS los links de Drive en el texto
  // Patrón 1: [Texto](url) - formato markdown
  const markdownLinksPattern = /\[([^\]]*)\]\((https?:\/\/drive\.google\.com[^\)]+)\)/gi;
  const markdownMatches = [...text.matchAll(markdownLinksPattern)];

  // Patrón 2: - Imagen N: url - formato de lista simple
  const simpleLinksPattern = /-\s*(?:Imagen|Image)\s*\d+\s*:\s*(https?:\/\/drive\.google\.com[^\s\n]+)/gi;
  const simpleMatches = [...text.matchAll(simpleLinksPattern)];

  // Patrón 3: - Link Imagen: url - formato en descripción de propiedad
  const linkImagenPattern = /-\s*Link\s+(?:Imagen|Image)\s*:\s*(https?:\/\/drive\.google\.com[^\s\n]+)/gi;
  const linkImagenMatches = [...text.matchAll(linkImagenPattern)];

  // Combinar todos los tipos de matches
  let allMatches = [];

  if (markdownMatches.length > 0) {
    allMatches = markdownMatches.map(m => ({ label: m[1], url: m[2], type: 'markdown' }));
  } else if (linkImagenMatches.length > 0) {
    allMatches = linkImagenMatches.map((m, i) => ({ label: 'Link Imagen', url: m[1], type: 'linkImagen' }));
  } else if (simpleMatches.length > 0) {
    allMatches = simpleMatches.map((m, i) => ({ label: `Imagen ${i + 1}`, url: m[1], type: 'simple' }));
  }

  if (allMatches.length === 0) {
    // No hay links, retornar el texto tal cual
    out.push({
      json: {
        text_clean: text,
        image_link: null,
        is_image_list: false,
        ...item.json
      }
    });
    continue;
  }

  // Detectar si es una lista de imágenes
  // Criterio: múltiples links Y el texto sin links es mínimo
  let textWithoutLinks = text
    .replace(/\d+\.\s*\[([^\]]*)\]\(https?:\/\/[^\)]+\)\s*/gi, '') // 1. [Imagen](url)
    .replace(/\[([^\]]*)\]\(https?:\/\/[^\)]+\)\s*/gi, '') // [Imagen 1](url)
    .replace(/-\s*(?:Imagen|Image)\s*\d+\s*:\s*https?:\/\/[^\s\n]+\s*/gi, '') // - Imagen N: url
    .replace(/-\s*Link\s+(?:Imagen|Image)\s*:\s*https?:\/\/[^\s\n]+\s*/gi, '') // - Link Imagen: url
    .trim();

  const isImageList = allMatches.length > 1 && textWithoutLinks.length < 50;

  if (isImageList) {
    // CASO 2: Lista de imágenes - crear un item por cada link
    allMatches.forEach((match, index) => {
      out.push({
        json: {
          text_clean: "", // String vacío - no enviar texto con cada imagen
          image_link: match.url,
          image_index: index + 1,
          total_images: allMatches.length,
          is_image_list: true,
          // Copiar otros campos del item original excepto 'text'
          ...(({ text, ...rest }) => rest)(item.json)
        }
      });
    });
  } else {
    // CASO 1: Texto descriptivo con imagen única - limpiar y extraer
    const imageLink = allMatches[0].url;

    // Limpiar el texto removiendo la línea del link (todos los formatos)
    let textClean = text
      .replace(/-\s*Link\s+(?:Imagen|Image)\s*:\s*https?:\/\/[^\s\n]+\s*/gi, '') // - Link Imagen: url
      .replace(/-\s*(?:Imagen|Image)\s*\d*\s*:\s*https?:\/\/[^\s\n]+\s*/gi, '') // - Imagen N: url
      .replace(/-\s*\[([^\]]*(?:Imagen|Image)[^\]]*)\]\(https?:\/\/[^\)]+\)\s*/gi, ''); // - [Ver Imagen](url)
    textClean = textClean.replace(/\n+$/, '');

    out.push({
      json: {
        text_clean: textClean,
        image_link: imageLink,
        is_image_list: false,
        ...item.json
      }
    });
  }
}

return out;

const items = $input.all();

// Si no hay items O el primer item está vacío, el lead no existe
if (items.length === 0 || !items[0].json.Telefono) {
  return [{
    json: {
      Telefono: null,
      lead_encontrado: false,
      row_number: null,
    }
  }];
}

// Tomar la última coincidencia (más reciente)
const leadMasReciente = items[items.length - 1];

// Regresar un NUEVO item copiando todo y forzando row_number
return [{
  json: {
    ...leadMasReciente.json,
    row_number: leadMasReciente.json.row_number ?? null,
    lead_encontrado: true,
  },
  pairedItem: { item: items.length - 1 },
}];

// Nodo: "Preparar_Actualizacion_Lead"
// Verifica si hay datos nuevos del cliente o preferencias para actualizar el lead
// Entrada: output de Parsear_Respuesta
// Salida: items con bandera actualizar_lead y datos_actualizacion

const items = $input.all();

return items.map(item => {
  const datos = item.json.datos_cliente || {};
  const prefs = item.json.preferencias || {};

  // 1. Verificar si hay un nombre real (no null)
  const tieneNombre = datos.nombre !== null && datos.nombre !== '';

  // 2. Verificar si hay email
  const tieneEmail = datos.email !== null && datos.email !== '';

  // 3. Verificar si hay preferencias nuevas (cualquiera que no sea null/vacío)
  const tienePreferencias = 
    prefs.operacion !== null ||
    prefs.tipo !== null ||
    prefs.zona !== null ||
    (prefs.presupuesto_min !== null && prefs.presupuesto_min > 0) ||
    (prefs.presupuesto_max !== null && prefs.presupuesto_max > 0) ||
    (prefs.habitaciones_min !== null && prefs.habitaciones_min > 0) ||
    (prefs.habitaciones_max !== null && prefs.habitaciones_max > 0) ||
    (Array.isArray(prefs.amenidades_deseadas) && prefs.amenidades_deseadas.length > 0) ||
    prefs.notas_adicionales !== null;

  // 4. Si NO hay nada nuevo, pasar el item sin bandera de actualización
  if (!tieneNombre && !tieneEmail && !tienePreferencias) {
    return {
      json: {
        ...item.json,
        actualizar_lead: false,
        datos_actualizacion: null
      }
    };
  }

  // 5. Preparar objeto de actualización (solo campos con valores reales)
  const datos_actualizacion = {
    row_number: datos.lead_row_number,
    Ultima_actualizacion: $now.setZone('America/Mexico_City').toFormat('yyyy-MM-dd HH:mm:ss')
  };

  // --- Datos del cliente ---
  if (tieneNombre) {
    datos_actualizacion.Nombre = datos.nombre;
  }

  if (tieneEmail) {
    datos_actualizacion.Email = datos.email;
  }

  // --- Preferencias ---
  if (prefs.operacion !== null) {
    datos_actualizacion.Tipo_operacion = prefs.operacion;
  }

  if (prefs.tipo !== null) {
    datos_actualizacion.Tipo_propiedad = prefs.tipo;
  }

  if (prefs.zona !== null) {
    datos_actualizacion.Zona = prefs.zona;
  }

  if (prefs.presupuesto_min !== null && prefs.presupuesto_min > 0) {
    datos_actualizacion.Presupuesto_min = prefs.presupuesto_min.toString();
  }

  if (prefs.presupuesto_max !== null && prefs.presupuesto_max > 0) {
    datos_actualizacion.Presupuesto_max = prefs.presupuesto_max.toString();
  }

  if (prefs.habitaciones_min !== null && prefs.habitaciones_min > 0) {
    datos_actualizacion.Recamaras_min = prefs.habitaciones_min.toString();
  }

  if (prefs.habitaciones_max !== null && prefs.habitaciones_max > 0) {
    datos_actualizacion.Recamaras_max = prefs.habitaciones_max.toString();
  }

  if (Array.isArray(prefs.amenidades_deseadas) && prefs.amenidades_deseadas.length > 0) {
    datos_actualizacion.Amenidades = prefs.amenidades_deseadas.join(', ');
  }

  if (prefs.notas_adicionales !== null) {
    datos_actualizacion.Notas = prefs.notas_adicionales;
  }

  return {
    json: {
      ...item.json,
      actualizar_lead: true,
      datos_actualizacion: datos_actualizacion
    }
  };
});

// Code node — Run Once for All Items
// Nombre sugerido: Parsear_Respuesta
// Entrada: { json: { output: "<string JSON>" } }
// Salida: N items (uno por cada segmento dividido por \n\n) con { message, part_index, parts_total, ...metadatos }

const items = $input.all();

// Helpers
const smartToAscii = (s) =>
  s.replace(/[""„‟]/g, '"').replace(/[''‚‛]/g, "'").replace(/\u00A0/g, ' ');

// Extrae el primer bloque {...} o [...] razonable
function extractJsonBlock(s) {
  if (typeof s !== 'string') return null;
  let t = smartToAscii(s).trim();
  // ```json ... ```
  const fenced = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) t = fenced[1].trim();
  // Primer bloque { ... } o [ ... ]
  const start = t.search(/[\{\[]/);
  if (start === -1) return null;
  t = t.slice(start);
  // Balanceo sencillo
  let depth = 0, end = -1, inStr = false, esc = false;
  const stack = [];
  const pairs = { '{': '}', '[': ']' };
  for (let i = 0; i < t.length; i++) {
    const ch = t[i];
    if (inStr) {
      if (esc) { esc = false; }
      else if (ch === '\\') { esc = true; }
      else if (ch === '"') { inStr = false; }
      continue;
    }
    if (ch === '"') { inStr = true; continue; }
    if (ch === '{' || ch === '[') { stack.push(pairs[ch]); depth++; continue; }
    if ((ch === '}' || ch === ']') && depth > 0) {
      const expected = stack.pop();
      if (ch !== expected) return null;
      depth--;
      if (depth === 0) { end = i; break; }
    }
  }
  if (end === -1) return null;
  // Quita comas colgantes simples
  const candidate = t.slice(0, end + 1).replace(/,\s*([}\]])/g, '$1');
  return candidate.trim();
}

function safeParse(v) {
  if (v == null) return null;
  if (typeof v === 'object') return v;
  if (typeof v === 'string') {
    const block = extractJsonBlock(v);
    if (!block) return null;
    try { return JSON.parse(block); } catch { return null; }
  }
  return null;
}

const out = [];

for (const it of items) {
  // 1) Capa exterior
  const raw = it.json?.output ?? it.json ?? null;
  let parsed = safeParse(raw) ?? {};

  // 2) Si hay otra capa en "output"
  if (typeof parsed?.output === 'string') {
    const inner = safeParse(parsed.output);
    if (inner) parsed = inner;
  } else if (parsed && typeof parsed?.output === 'object') {
    parsed = parsed.output;
  }

  // 3) Extraer el reply y dividir por \n\n
  let replyText = typeof parsed?.reply === 'string' ? parsed.reply : '';

  // Convertir los \\n literales a saltos de línea reales
  replyText = replyText.replace(/\\n/g, '\n');

  // Dividimos por doble salto de línea
  let parts = replyText.split('\n\n').filter(part => part.trim().length > 0);

  // Si no hay partes después de dividir, usar el texto completo
  if (parts.length === 0 && replyText.trim().length > 0) {
    parts = [replyText.trim()];
  }

  // 4) Extraer metadatos con la NUEVA estructura
  const meta = {
    // Campos principales
    intencion: parsed?.intencion ?? 'pregunta_general',
    paso: parsed?.paso ?? '1',
    requiere_agente_humano: Boolean(parsed?.requiere_agente_humano ?? false),

    // Datos del cliente (nueva estructura)
    datos_cliente: {
      lead_row_number: parsed?.datos_cliente?.lead_row_number ?? null,
      nombre: parsed?.datos_cliente?.nombre ?? null,
      telefono: parsed?.datos_cliente?.telefono ?? null,
      email: parsed?.datos_cliente?.email ?? null
    },

    // Preferencias (nueva estructura)
    preferencias: {
      operacion: parsed?.preferencias?.operacion ?? null,
      tipo: parsed?.preferencias?.tipo ?? null,
      zona: parsed?.preferencias?.zona ?? null,
      presupuesto_min: parsed?.preferencias?.presupuesto_min ?? null,
      presupuesto_max: parsed?.preferencias?.presupuesto_max ?? null,
      habitaciones_min: parsed?.preferencias?.habitaciones_min ?? null,
      habitaciones_max: parsed?.preferencias?.habitaciones_max ?? null,
      amenidades_deseadas: Array.isArray(parsed?.preferencias?.amenidades_deseadas) 
        ? parsed.preferencias.amenidades_deseadas 
        : [],
      notas_adicionales: parsed?.preferencias?.notas_adicionales ?? null
    },

    // Recomendaciones (array de propiedades)
    recomendaciones: Array.isArray(parsed?.recomendaciones) 
      ? parsed.recomendaciones 
      : []
  };

  // 5) Si no hay parts, emite un item "vacío" para no romper el flujo
  if (parts.length === 0) {
    out.push({
      json: {
        message: '',
        part_index: 0,
        parts_total: 0,
        ...meta
      }
    });
    continue;
  }

  // 6) Emite un item por cada parte del mensaje
  const total = parts.length;
  parts.forEach((msg, idx) => {
    out.push({
      json: {
        message: msg.trim(),
        part_index: idx + 1,   // 1-based
        parts_total: total,
        ...meta
      }
    });
  });
}

return out;

const items = $input.all();

return items.map((item) => {
  const ultimaActualizacion = item.json.Ultima_actualizacion;

  const ahora = new Date();
  const ultimaFecha = new Date(ultimaActualizacion.replace(' ', 'T') + '-06:00');

  const diferenciaMs = ahora - ultimaFecha;
  const diferenciaHoras = diferenciaMs / (1000 * 60 * 60);

  return {
    json: {
      ...item.json,
      horas_transcurridas: diferenciaHoras,
      row_number: item.json.row_number ?? null,
    },
    pairedItem: item.pairedItem ?? { item: 0 },
  };
});

const items = $input.all();

// Si no hay items O el primer item está vacío, el lead no existe
if (items.length === 0 || !items[0].json.Telefono) {
  return [{
    json: {
      Telefono: null,
      lead_encontrado: false,
      row_number: null,
    }
  }];
}

// Tomar la última coincidencia (más reciente)
const leadMasReciente = items[items.length - 1];

// Regresar un NUEVO item copiando todo y forzando row_number
return [{
  json: {
    ...leadMasReciente.json,
    row_number: leadMasReciente.json.row_number ?? null,
    lead_encontrado: true,
  },
  pairedItem: { item: items.length - 1 },
}];
